<template>
  <section class="login h-full w-full flex flex-col">
    <div class="flex gap-1.5 items-center justify-end">
      <NuxtLink :to="{ name: 'password-restore' }">
        <Button variant="secondary" size="sm">Restore Password</Button>
      </NuxtLink>
      <NuxtLink :to="{ name: 'sign-up' }">
        <Button variant="secondary" size="sm">Sign Up</Button>
      </NuxtLink>
    </div>
    <form
      class="self-center flex flex-col gap-6 p-6 flex-auto w-full justify-center max-w-[552px] max-lg:px-0"
      @submit="onSubmit"
    >
      <h1 class="font-semibold text-2xl leading-6">Log In</h1>
      <FormItemWrapper name="email" label="Email" item-class="col-span-2">
        <template #default="{ slots }">
          <Input
            id="email"
            type="text"
            placeholder="name@example.com"
            :disabled="isSigningIn"
            v-bind="slots.componentField"
          />
        </template>
      </FormItemWrapper>
      <FormItemWrapper name="password" label="Password" item-class="col-span-2">
        <template #default="{ slots }">
          <KitFormPasswordInput
            id="password"
            placeholder="********"
            :component-field="slots.componentField"
            :disabled="isSigningIn"
            autocomplete="password"
          />
        </template>
      </FormItemWrapper>
      <Button variant="default" class="w-full h-10" :loading="isSigningIn" :disabled="isSigningIn">Log In</Button>
      <p class="text-center text-description text-sm leading-5 self-center px-4 sm:px-10">
        By logging in, you agree to our<br />
        <NuxtLink :to="{ name: 'privacy' }" class="underline">Terms of Service</NuxtLink>
        and
        <NuxtLink :to="{ name: 'privacy' }" class="underline">Privacy Policy</NuxtLink>
        <span>.</span>
      </p>
    </form>
  </section>
</template>

<script setup lang="ts">
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { requestAndRegisterPushNotifications, resolveNotificationPermissions } from '~/plugins/notifications';
import { ensureDeviceLinked } from '~/utils/mobile/ensureDeviceLinked';
import { Capacitor } from '@capacitor/core';
import { markPrefetched } from '~/plugins/offlinePrefetch';

useSeoMeta({
  title: 'Log In',
  description: 'Secure access point to your account with robust authentication mechanisms.',
});

definePageMeta({
  layout: 'login',
  auth: {
    unauthenticatedOnly: true,
    navigateAuthenticatedTo: '/projects',
  },
});

if (Capacitor.isNativePlatform()) {
  await resolveNotificationPermissions();
}

const isSigningIn = ref<boolean>(false);

const formSchema = toTypedSchema(
  z.object({
    email: z.string({ message: 'Email is required' }).email(),
    password: z.string({ message: 'Password is required' }).trim().nonempty({ message: 'Password is required' }),
  })
);

const { handleSubmit } = useForm({
  validationSchema: formSchema,
});

const { signIn } = useAuth();
const route = useRoute();

const onSubmit = handleSubmit(async (values) => {
  if (isSigningIn.value) return;

  try {
    isSigningIn.value = true;

    const body = new FormData();
    body.append('username', values.email);
    body.append('password', values.password);

    const callbackUrl = getSafeRedirectUrl(route);

    await signIn(body, {
      callbackUrl,
    });

    await initializeDeviceAfterLogin();
    prefetchOfflineData();
    await markPrefetched();

    // await navigateTo(callbackUrl); mooved to useAuth signIn callback
  } catch (error: any) {
    showToastError(error.message, 'Authorization error');
  } finally {
    isSigningIn.value = false;
  }
});

async function initializeDeviceAfterLogin() {
  if (!Capacitor.isNativePlatform()) return;
  await ensureDeviceLinked();
  await requestAndRegisterPushNotifications();
}
</script>

<style scoped lang="scss"></style>
